Here is a PoC code I used to generate colors according to the spec received from [~accountid:628236520685de006fcfbe7d] 
It needs confirmation before final implementation, as still some changes may be needed (see the linked Slack thread)

{noformat}<html>
    <head>
        <style>
            .box {
                width: 50px;
                height: 50px;
                border: 1px solid #ddd;
                display: inline-block;
                margin: 5px;
            }
        </style>
        <script>
            function RGBToHSL(r, g, b) {
                r /= 255;
                g /= 255;
                b /= 255;
                const l = Math.max(r, g, b);
                const s = l - Math.min(r, g, b);
                const h = s
                    ? l === r
                        ? (g - b) / s
                        : l === g
                        ? 2 + (b - r) / s
                        : 4 + (r - g) / s
                    : 0;
                return {
                    h: 60 * h < 0 ? 60 * h + 360 : 60 * h,
                    s: 100 * (s ? (l <= 0.5 ? s / (2 * l - s) : s / (2 - (2 * l - s))) : 0),
                    l: (100 * (2 * l - s)) / 2,
                };
            };

            function HSLToRGB(h, s, l) {
                s /= 100;
                l /= 100;
                const k = n => (n + h / 30) % 12;
                const a = s * Math.min(l, 1 - l);
                const f = n =>
                    l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
                return {
                    r: 255 * f(0),
                    g: 255 * f(8),
                    b: 255 * f(4)
                };
            };

            function hexToRGB(hex) {
                var result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
                return result ? {
                    r: parseInt(result[1], 16),
                    g: parseInt(result[2], 16),
                    b: parseInt(result[3], 16)
                } : null;
            }

            function generate() {
                const alpha = {
                    "light-main": 1,
                    "light-icon": 1,
                    "light-text": 1,
                    "light-close-icon": 1,
                    "light-bg": 0.12,
                    "light-bg-active": 0.24,
                    "light-activated": 1,
                    "light-border": 0.48,
                    "dark-main": 1,
                    "dark-icon": 1,
                    "dark-text": 1,
                    "dark-close-icon": 1,
                    "dark-bg": 0.12,
                    "dark-bg-active": 0.24,
                    "dark-activated": 1,
                    "dark-border": 0.64,
                };
                const input = document.getElementById("main-color");
                const mainRGB = hexToRGB(input.value.toLowerCase());
                const mainHSL = RGBToHSL(mainRGB.r, mainRGB.g, mainRGB.b);
                const darkMainHSL = {h: mainHSL.h, l: 75, s: mainHSL.s};
                const darkMainRGB = HSLToRGB(darkMainHSL.h, darkMainHSL.s, darkMainHSL.l);


                let content = "324";

                Object.entries(alpha).forEach(([k, v]) => {
                    const color = (k.startsWith("light")) ? mainRGB : darkMainRGB;
                    document.getElementById(k).style["background-color"] = `rgba(${color.r}, ${color.g}, ${color.b}, ${v})`;
                });

                document.getElementById("result").innerText = content;
            }
        </script>
