{noformat}    public getCacheKey(event: TargetingEventCacheEntity, query: ParametersRequestIdentifierSource) {
        // cache key will be built even for invalid requests, but this is OK because only valid and successful requests are cached
        const eventKey = event.key;
        const rawAuthId = this.getRawAuthId(event.auth_type, query);
        const cityId = query.city_id ? query.city_id.toString() : "";
        const country = query.country ? query.country : "";
        const appVersion = query.app_version ? query.app_version : "";
        const language = query.language ? query.language : "";
        return `${eventKey}:${rawAuthId}:${cityId}:${country}:${appVersion}:${language}`;
